// What's new to try: the newest features, with how to try each one and a Show me that points at
// the control. Ticks are kept on this device (not in the project), and a feature ticks itself
// the first time it is actually used.
//
// Every batch that ships adds its features at the top of this list, with the date it went live.

export const NEW_FEATURES = [
  { id: 'bodyQuick', date: '2026-11-24', title: 'Body opens straight away', how: 'Open Body, close it, then open it again. It opens at once with every measurement in inches beside its slider. Before, it measured the whole body again each time it opened, though nothing had changed. Move a slider and the inches still follow it.', show: 'bodyInches' },
  { id: 'pickQuick', date: '2026-11-24', title: 'The first tap is quick in a big project', how: 'Open a project with many tattoos, wait a moment, then tap a line in Layers or a tattoo on the body. It is picked straight away, as quick as every tap after it. Before, the first pick after opening or changing the body paused for about a third of a second while the app measured every tattoo.', show: 'gap' },
  { id: 'sliderQuick', date: '2026-11-24', title: 'Body sliders keep up in a big project', how: 'In a project with many tattoos, open Body and slide Weight, Muscle or a fine-tune slider. The body and every tattoo on it follow your finger with less than half the wait there was before, when each step could take over half a second.', show: 'definition' },
  { id: 'undoQuick', date: '2026-11-24', title: 'Undo is quick in a big project', how: 'In a project with many tattoos, rename one, move one or tap Sort by area in Layers, then tap Undo and Redo, or tap with two fingers. The step comes back at once. Before, every undo redrew the ink of every tattoo, which in a big project was a pause you could feel. Undoing a body slider still reshapes the body.', show: 'tapUndo' },
  { id: 'dupQuick', date: '2026-11-24', title: 'Duplicate is quick in a big project', how: 'In a project with many tattoos, select one and press Cmd+D, or tap Duplicate in More controls or in its Layers line. The copy shows at once. Before, it could hang for a few seconds while the app read every picture again.', show: 'duplicate' },
  { id: 'gapQuick', date: '2026-11-24', title: 'Big projects stay quick after a move', how: 'In a project with many tattoos, drag one to a new spot and lift your finger, or tap from one tattoo to the next. The line under its size that says how far it is from the nearest tattoo now comes straight away, without the pause of up to a second there was before.', show: 'gap' },
  { id: 'layersRoom', date: '2026-11-24', title: 'Layers keeps room beside the edit panel', how: 'On an iPad on its side, open Layers and tap a tattoo. At least three lines of Layers still show above its edit panel, and the panel scrolls inside for the rest. Before, Layers could shrink to under two lines.', show: 'sheetColumn' },
  { id: 'barAlwaysFits', date: '2026-11-24', title: 'Share stays on screen', how: 'Look at the top right on an iPad on its side, also in a smaller Chrome window: Share and the account button are always inside the screen, and Full body, Front and the other views move to their own row when the top row is full. Before, the bar could run past the edge a moment after the app opened.', show: 'barFits' },
  { id: 'copyUnder', date: '2026-11-23', title: 'A copy goes right under its original in Layers', how: 'Select a tattoo, open More controls and tap Duplicate or Copy to other side, or press Cmd+D. In Layers the copy is the line right under the tattoo it came from, the way Duplicate in a Layers line already works, and its line comes into view even in a long list on an iPad held upright. Before, it went to the bottom of the list, far from the original when you have many layers.', show: 'duplicate' },
  { id: 'dupPlan', date: '2026-11-23', title: 'Duplicate of ink you have makes a plan', how: 'Select a tattoo that is on your skin, open More controls and tap Duplicate, or press Cmd+D. The copy beside it is a planned piece you can move and size, with its own approval. Before, it came out marked On my skin but loose, kept the original\'s approval, and a changed Procreate layer brought back took it away. On an arm or leg it now lands beside the original instead of exactly on top of it.', show: 'duplicate' },
  { id: 'otherSidePlan', date: '2026-11-23', title: 'Copy to other side of ink you have makes a plan', how: 'Select a tattoo that is on your skin, open More controls and tap Copy to other side. The twin is a planned piece you can move and size, with its own approval. Before, it came out marked On my skin, so it could not be moved.', show: 'otherSide' },
  { id: 'undoFolders', date: '2026-11-23', title: 'Undo says what it did to folders and layers', how: 'In Layers, tap Sort by area, then tap Undo: the message says it undid the folders. Renaming a folder or taking a tattoo out of one is named the same way, like Undid taking Rose out of Chest, and so are a merge and hiding or locking several picked lines at once. Press and hold Undo for Go back to, which uses the same words. Before, it said removing one of the merged pieces, changes to a number of tattoos, or the last change.', show: 'areaFolders' },
  { id: 'warpHeld', date: '2026-11-23', title: 'Bend and warp keeps a drag when you tap its bar', how: 'Select a tattoo and tap Bend and warp. Hold a dot with one finger and, before lifting it, tap Distort, a grid size or Done with another. What you dragged stays as one undo step and the next dot moves at once. Before, the dots stopped answering until the bar was closed, and Done could leave that change unsaved.', show: 'warpInk' },
  { id: 'areaFollows', date: '2026-11-23', title: 'Area folders keep up when a tattoo moves', how: 'After Sort by area in Layers, move a tattoo to another part of the body, or use Copy to other side on one: it goes into the folder for where it now sits, and a folder for that area is made if there is none. A folder whose last tattoo is deleted or moved away goes too. Tattoos you put in a folder yourself stay where you put them.', show: 'areaFolders' },
  { id: 'viewFollows', date: '2026-11-23', title: 'A new tattoo shows even in On my skin', how: 'At the top of Layers, tap On my skin, then add a picture with the + button. The view goes back to All with a message, so the new planned tattoo shows on the body. The same happens when you pick a dimmed line or switch a tattoo between On my skin and Planned. Before, it was selected but nothing showed.', show: 'layerViews' },
  { id: 'swipeTapClose', date: '2026-11-23', title: 'Tap a swiped line to close it', how: 'In Layers, swipe a line to the left so Lock, Duplicate and Delete show, then tap the line itself. It slides back and nothing else happens. Before, the tap could land on the eye that slid along with it and hide the tattoo.', show: 'layerSwipe' },
  { id: 'tapOnHandle', date: '2026-11-23', title: 'Two-finger undo works next to the handles', how: 'Select a tattoo, change its size, then tap with two fingers so that one of them lands on the round size or turn handle. It undoes the change and the tattoo stays selected. Before, the handle kept that finger to itself, so nothing was undone and the tap dropped the tattoo.', show: 'tapUndo' },
  { id: 'areaFolders', date: '2026-11-22', title: 'Folders by body area', how: 'Open Layers and tap Sort by area at the foot. Every tattoo goes into a folder for where it sits on you, like Left thigh, Right forearm or Chest, and the folders start folded so the list is short. Folders you made yourself keep what you put in them. Fold all or Open all is beside it. Undo puts everything back the way it was.', show: 'areaFolders' },
  { id: 'folderOpen', date: '2026-11-22', title: 'Tap a folder to see it on the body', how: 'In Layers, tap a folder\u2019s name: it opens and the view turns to every piece in it at once. Tap the eye beside it to hide or show the whole folder. The dots give Show only this folder, Show everything, its name to type, Pick them for the bar\u2019s actions, and Take them out of the folder. Drag a line onto a folder to put it in.', show: 'folderOpen' },
  { id: 'tapUndo', date: '2026-11-22', title: 'Two-finger tap to undo', how: 'As in Procreate: tap the body with two fingers to undo the last change, or with three fingers to redo it. Hold two fingers still on the screen to keep undoing, one step after another, until you lift them. A message says what each one put back. It works in Clean up too. A pinch, a pan or a turn is never taken for a tap.', show: 'tapUndo' },
  { id: 'layerSelect', date: '2026-11-22', title: 'Pick several layers and change them together', how: 'Open Layers and tap Select at the bottom, then tap the lines you want (or Pick all). The bar at the top hides or shows them, duplicates them in place, groups them or takes them out of their group, locks them, merges them into one, or deletes them, each as one undo step. More opens moving them together, ink strength and solo. Tattoos already on your skin ask once before they are deleted. Tap Done when you are finished.', show: 'layerSelect' },
  { id: 'layerViews', date: '2026-11-22', title: 'All, On my skin or Planned', how: 'At the top of Layers, tap On my skin to see only the tattoos you already have, Planned to see only your plans, or All for everything, each with how many there are. Only the screen changes: the project is not, and everything shows again after a reload.', show: 'layerViews' },
  { id: 'layerSwipe', date: '2026-11-22', title: 'Swipe a layer, the Procreate way', how: 'Open Layers at the right. Swipe a line to the left for Lock, Duplicate and Delete behind it. Swipe a line to the right to pick it, then swipe right on more: a bar at the top changes all the picked ones at once. Duplicate makes an exact copy in the same place, bend, colour and size included. Tap the selected line for all its options, with its name to type and Zoom to it.', show: 'layerSwipe' },
  { id: 'layerMerge', date: '2026-11-22', title: 'Merge tattoos into one', how: 'In Layers, put two fingers on two lines and pinch them together: every line from one finger to the other becomes one tattoo, exactly as it looks on your skin, bends, blend modes and colour changes included. Merge down in a line\u2019s options merges it into the line under it. One Undo puts them all back, and the tattoo merged into keeps its earlier picture under Design versions.', show: 'layerMerge' },
  { id: 'layerReorder', date: '2026-11-22', title: 'Drag a layer to a new place', how: 'In Layers, press and hold a line until it lifts, then drag it up or down and let go where the line shows. Drop it on a group\u2019s heading, or among its lines, to put it in that group.', show: 'layerReorder' },
  { id: 'shotsBent', date: '2026-11-22', title: 'Close pictures aim at a bent tattoo', how: 'Bend a tattoo narrower with Bend and warp, then open Share and make How it ages: each picture is centred on the bent piece and fills the frame the way a plain one does. The same goes for From a distance, If your body changes, As you move and the close-ups on the artist sheet. Before, they aimed at the flat file, so a bent piece came out small and off to one side.', show: 'agingSheet' },
  { id: 'wrapBent', date: '2026-11-22', title: 'Wrap it round fits a bent tattoo', how: 'Put a long piece on an arm or leg, bend it narrower with Bend and warp, then look under its name: how far round it goes now reads the bent piece, and Wrap it round makes the bent piece meet itself at the back. Before, both went by the flat file.', show: 'wrapGrab' },
  { id: 'grabBent', date: '2026-11-22', title: 'A bent tattoo moves only from where it is', how: 'Bend a tattoo narrower with Bend and warp, tap Done, then drag on the bare skin just beside it: the view turns, as it does anywhere off a tattoo. A drag on the bent piece still moves it. Before, the whole square of the flat file still grabbed it, bare skin included.', show: 'warpInk' },
  { id: 'coverBent', date: '2026-11-22', title: 'How covered you are counts a bent tattoo right', how: 'Bend a tattoo with Bend and warp, then open Preview > Open skin. The line on how covered each area is, and the share of your skin under ink, now count the skin the bent piece covers. Before, a tattoo squeezed narrower still counted at its flat size.', show: 'room' },
  { id: 'picsBent', date: '2026-11-22', title: 'More pictures read a bent tattoo right', how: 'Bend a tattoo with Bend and warp, then open Share and make If your body changes, or Arms and legs unrolled. The size written under the tattoo is now the size the bent piece fills on your skin, as it is under its name. The pain map reading, How it holds up there and Find room for it also go by the bent size.', show: 'bodyChange' },
  { id: 'spotsFollow', date: '2026-11-22', title: 'Try other spots keeps up', how: 'Select a tattoo, open More controls and tap Try other spots, then leave it open. Pinch the tattoo bigger or smaller, press the size keys, or tap Undo: once you lift your finger, the line under each spot (how much it hurts, what hides it, whether it fits) changes to match. Tap another tattoo and the title follows it. Before, it kept what it said when it opened.', show: 'spotCompare' },
  { id: 'sizesBent', date: '2026-11-22', title: 'Sizes read a bent tattoo right', how: 'Bend a tattoo with Bend and warp, then make Share > Picture with sizes or Three sizes, send the plan as a message or ask for approval. Each now gives the size the bent piece fills on your skin, the same as the size under its name, and the dashed box in Picture with sizes goes round the bent piece itself. Time to tattoo, the everyday size, Width (inches) and the 1 to 4 in buttons in More controls do too, so 2 in makes the bent piece 2 inches wide, and Try other spots says whether the bent piece fits each spot. Before, they used the size of the flat file.', show: 'sizesBent' },
  { id: 'tryOnBent', date: '2026-11-22', title: 'Try on a bent tattoo', how: 'Bend a tattoo with Bend and warp, then open More controls and tap Try on with camera. The tattoo over your camera or photo is bent the way it is on the body, at the size it fills, and the line under it gives that size. Before, it showed the flat file.', show: 'tryOnBent' },
  { id: 'flatFiles', date: '2026-11-22', title: 'Prints match the body', how: 'Mirror or flip a tattoo, or bend it with Bend and warp, then open Share and make the artist sheet or Print at real size. Each picture now reads the way the tattoo sits on you. Before, the artist sheet showed the plain file and a flipped tattoo printed upright. The print says when it is mirrored or flipped, and From a distance measures a bent tattoo\u2019s lines as they are drawn.', show: 'flatFiles' },
  { id: 'realSizeBent', date: '2026-11-22', title: 'Real size on screen shows a bent tattoo', how: 'Bend a tattoo with Bend and warp, then open More controls and tap Real size on screen. It shows the bent piece at the size it fills on your skin, where before it showed the flat file at its old size.', show: 'realSize' },
  { id: 'warpTrim', date: '2026-11-21', title: 'A bent tattoo keeps its shape when trimmed', how: 'Bend a tattoo with Bend and warp, then tap Trim to the ink under its name, or crop it in Clean up and tap Done. The bent piece stays on the same skin, the same size and bent the same way. Before, it slid a few millimetres and lost part of its bend.', show: 'warpInk' },
  { id: 'moveLight', date: '2026-11-21', title: 'Moving a tattoo near another is lighter', how: 'With two tattoos close together, select one and drag it about, then let go. The line under its size that says how far it is from the other tattoo updates at once, without reading the whole picture again after every move.', show: 'gap' },
  { id: 'barFits', date: '2026-11-21', title: 'The top bar fits a narrow iPad', how: 'On an iPad mini held upright, a big iPad split in half or Ink Atlas in a window beside another app, Share and the account button no longer run off the right edge. With a preview on, the Preview button says just Preview where room is short (it stays filled in), and on the narrowest screens Body, Preview and Plan show their icons only. The whole app also no longer slides sideways and stays stuck there.', show: 'barFits' },
  { id: 'warpInk', date: '2026-11-21', title: 'Bend and warp a tattoo on the body', how: 'Select a tattoo and tap Bend and warp. Drag a dot on the grid to bend that part of the tattoo, right on the skin. Distort stretches the four corners in perspective, and Arc curves the whole piece up or down. Reset puts it back flat, and Undo takes back each drag. The artwork itself never changes, and stencils, prints and the 3D files carry the new shape.', show: 'warpInk' },
  { id: 'posedShape', date: '2026-11-21', title: 'Change your shape while posed', how: 'Pick a pose under Preview > Pose, then open Body and slide Weight or Muscle. The posed body keeps up with your finger instead of catching between frames.', show: 'posedShape' },
  { id: 'bentJoint', date: '2026-11-21', title: 'Ink over a bent elbow or knee', how: 'Put a tattoo over the point of your elbow or your knee, then Preview > Pose > Boxing guard or Squat. The skin stretches evenly across the joint, as real skin does, so the ink bends with it instead of one line turning into a thick smeared bar.', show: 'bentJoint' },
  { id: 'openOnce', date: '2026-11-21', title: 'A double tap opens one window', how: 'Select a tattoo and tap Clean up twice quickly: one workspace opens, not two stacked one over the other. Projects, Planning, Body tools, Fit to a photo, Artwork library and Placement tools under Plan do the same.', show: 'cleanup' },
  { id: 'wrapSmooth', date: '2026-11-21', title: 'Moving a plant in the wrap is smoother', how: 'Plan > Measured wrap, with the tattoo already there traced. On the design step, drag a plant over the old ink and nudge it about: the warning about old ink and protected gaps keeps up with it without the short pause after each move.', show: 'measuredWrap' },
  { id: 'tapLooks', date: '2026-11-21', title: 'No highlight left behind after a tap', how: 'Open Preview and tap Light, or tap a choice like Hard or Soft in Clean up: once your finger lifts, only the choice you picked stays highlighted. Before, the last row or segment you touched kept a grey highlight and looked picked.', show: 'light' },
  { id: 'panelScroll', date: '2026-11-20', title: 'Blend and colour scrolls with a finger', how: 'Select a tattoo and tap Blend and colour. Drag a finger up anywhere in the panel, even over a slider or a blend mode: the panel scrolls down to Recolour and Invert, and the body and the screen stay still. The Layers list and the list of comments scroll the same way when they are long.', show: 'blendModes' },
  { id: 'accountSend', date: '2026-11-20', title: 'A big project goes to your account', how: 'Tap the red line under Ink Atlas, or the account button with its !, then Put it in my account. It now shows your pictures going up, skips the ones already in your account, tries a picture again if the line drops, and waits for a big project however long it takes. If something still stops it, it says which step and why, and whether your account is answering.', show: 'accountFix' },
  { id: 'smoothEdits', date: '2026-11-20', title: 'Smoother Clean up on big pictures', how: 'Select a tattoo made from a large photo or drawing and tap Clean up: the end of each Erase or Restore stroke, each slider change and each Undo no longer pauses while the picture is copied. In Plan > Measured wrap, changing a tape number now redraws the picture on the 3D leg at the new size instead of keeping the old one. On a phone, the Layers rail steps aside while Tape measure, How I see it, Comments or Pain map is open, so its buttons are never half hidden.', show: 'cleanup' },
  { id: 'tapsThrough', date: '2026-11-20', title: 'Messages never block a tap', how: 'A message such as "Saved to your downloads" no longer catches a tap meant for the button under it. Open Share right after saving a file and tap the last card: it opens, even with the message still showing. The Preview menu also scrolls with a finger now when it is longer than the screen, tapping into a box such as a note or a board name no longer zooms the whole page in, Hard and Soft in Clean up are easier to hit, and in the light look the words you type in Body tools are dark enough to read.', show: 'tapsThrough' },
  { id: 'twoWindows', date: '2026-11-20', title: 'Safe with Ink Atlas open twice', how: 'With Ink Atlas open in two places on one device (two tabs, or the home-screen app and Chrome), a copy that comes back to the screen opens the newer save from the other one, so you never change an older copy. If both were changed, the other version is kept in Share > Find my saves and a message says so.', show: 'findSaves' },
  { id: 'panelTidy', date: '2026-11-20', title: 'An easier edit panel', how: 'Select a tattoo and open More controls: in the panel at the right, Size, Turn and Ink strength each get the whole width of the panel, so they are easier to set with a finger. Light in Preview shows its four choices two to a row, and the tip in Clean up no longer points the wrong way on an iPad held upright.', show: 'panelTidy' },
  { id: 'picsKept', date: '2026-11-20', title: 'Pictures kept safe with two copies open', how: 'With Ink Atlas open twice on one device (two tabs, or the home-screen app and Safari), one copy can no longer clear away pictures the other copy\'s save still uses. Nothing to do: Share > Find my saves lists every copy kept on this device.', show: 'findSaves' },
  { id: 'accountFix', date: '2026-11-20', title: 'Put it in your account in one tap', how: 'When your project could not go to your account, the line under Ink Atlas says so in red and the account button carries a !. Tap either one. It looks at the copy in your account first and says what it will do: when that copy is the one this device last saved, or has only the samples, one tap puts this project there. When it has other work, Keep both adds this one as its own project, and Replace that copy is a second step that keeps the old copy on this device first. It also shows why the last try did not go.', show: 'accountFix' },
  { id: 'lostPics', date: '2026-11-20', title: 'Put back a lost picture', how: 'A tattoo whose picture was lost shows as Artwork missing in its place. Tap it: under its name, Replace picture takes a photo or picture from Photos or Files and puts it on in the same place and width, on every copy that lost it, in one undo step. Look again searches every corner of this device and every folder of your account, and puts back each picture it finds. It also looks by itself when the app opens.', show: 'lostPics' },
  { id: 'findSaves', date: '2026-11-20', title: 'Find my saves', how: 'Share > Find my saves lists every copy of your work kept on this device: earlier saves, any save that could not be opened (with Save it as a file), and your projects, each with how many tattoos it holds. One tap opens it, and Undo brings back what was on screen. A blank or sample project is now never saved over your work or sent over the copy in your account, and if your tattoos are missing when the app opens it tells you where they still are.', show: 'findSaves' },
  { id: 'bodyScan', date: '2026-11-20', title: 'Bring in a 3D scan of yourself', how: 'Scan yourself with a free app like Scaniverse or Polycam (Body > How to scan yourself says how), export the model as GLB, OBJ or USDZ to Files, then Body > Bring in a 3D scan of me. The body is moved onto your scan, standing up and facing front, at your real height, with the sliders matched as near as they go. Tattoos, poses, wraps, measurements and every export work on it. It shows what the scan measures round your chest, waist, hips, arms and legs, beside your tape numbers if you typed them. Undo takes it off in one step, and the scan stays on this device.', show: 'bodyScan' },
  { id: 'measureMe', date: '2026-11-19', title: 'Measure me with a tape', how: 'Body > Measure me with a tape. One measurement a screen, each with a drawing of exactly where the tape goes: height, neck, shoulders, chest, waist, hips, upper arm, forearm, wrist, thigh, calf and ankle, then the arm, torso and leg lengths if you want them. Skip any you do not have. At the end the body fits itself to all of them at once and shows what you measured beside what the model measures, so you can see it is right. Undo puts it back in one step.', show: 'measureMe' },
  { id: 'numberPad', date: '2026-11-19', title: 'Typing a measurement keeps the screen', how: 'Tapping a number under Body > Fine-tune now opens a number pad of its own instead of the iPad keyboard, so nothing slides off the screen. It has ¼, ½ and ¾, a switch to cm, and Next to go straight to the next measurement. A keyboard you plug in still works.', show: 'numberPad' },
  { id: 'relaxedArms', date: '2026-11-19', title: 'Arms relaxed at your sides', how: 'Preview > Pose > Arms relaxed at sides, under the straight arms. The upper arms hang straight down and the elbows keep the small bend a real relaxed arm has, so the forearms come a little forward with the palms to your thighs. It hangs as close to the body as your shape allows, with the hands just off the thighs. Your tattoos stay on the same skin at their real size, and the arm sizes you typed in Body measure the same in this pose.', show: 'relaxedArms' },
  { id: 'elbowDetail', date: '2026-11-19', title: 'Clearer elbows', how: 'The elbows now show the point of the elbow behind, the bony bumps either side of it, a little loose skin over the point and the crease in front, on every body shape and in every pose, so you can plan around them. Leaner bodies show them a bit more, like real ones. Nothing about your tattoos or measurements changes.', show: 'elbowDetail' },
  { id: 'cleanupImage', date: '2026-11-20', title: 'Add an image while you clean up', how: 'In Clean up, tap Add image in the rail (just under Move) and pick a photo or picture from the iPad. It comes in on top, ready to drag, size with the corners, turn with the dot and flip. Set its Opacity and Blend (Multiply drops out white paper), then tap Place it to put it into the picture. Paste a picture works after Copy in Procreate or Photos, and on a keyboard Command V pastes and I adds one.', show: 'cleanup' },
  { id: 'cleanupRail', date: '2026-11-20', title: 'Photoshop-style tools in Clean up', how: 'Select a tattoo and tap Clean up. Every tool now sits in a rail down the left with its picture and name: Select, Magic wand, Move and Crop at the top, then Cut out, Background, Erase, Restore and Clone, then Adjust. The panel under the picture shows only the settings of the tool in use, with its key (E for Erase, W for the wand and so on).', show: 'cleanup' },
  { id: 'cleanupBrushes', date: '2026-11-20', title: 'Erase and Restore with Strength and a soft edge', how: 'In Clean up, pick Erase or Restore. Choose Hard or Soft, the brush size and Strength: at 40% one stroke takes away 40% however often you go over a spot, so you can fade ink gently. The ring under your finger or Pencil is the brush, at any zoom.', show: 'cleanup' },
  { id: 'cleanupWand', date: '2026-11-20', title: 'Magic wand and Refine edge', how: 'In Clean up, pick Magic wand and tap a colour: it selects that colour where it touches, or everywhere with Touching only off. Tolerance says how close a colour must be. Grow and Similar spread the selection, Invert flips it, and Refine edge moves, smooths or feathers its edge as you slide. Erase, Restore, Clone, Move and Adjust then change only what is selected.', show: 'cleanup' },
  { id: 'cleanupBackground', date: '2026-11-20', title: 'Remove the background in one tap', how: 'In Clean up, pick Background and tap Remove background. It finds the colour round the edge of the picture and takes it away; slide Background range to take more or less, and see it change as you slide. Just the edges keeps the same colour inside the design.', show: 'cleanup' },
  { id: 'cleanupAdjust', date: '2026-11-20', title: 'Levels, Curves and more', how: 'In Clean up, pick Adjust. Levels (with Auto), Curves (drag a point, tap the line to add one), Brightness and contrast, Threshold for a black stencil, Sharpen, Blur and Darker lines all show as you slide, each as one undo step. With a selection, only that part changes.', show: 'cleanup' },
  { id: 'cleanupClone', date: '2026-11-20', title: 'Clone and heal', how: 'In Clean up, pick Clone. Tap a clean spot to copy from (a cross marks it), then paint over a smudge, a crease or a stray mark. Heal keeps the shading of the spot you paint and takes only the detail, for paper texture or a shadow. Tap Pick where to copy from to choose again.', show: 'cleanup' },
  { id: 'cleanupHistory', date: '2026-11-20', title: 'History and before and after', how: 'In Clean up, tap the clock at the top to see every step in words (Crop, Background, Levels...). Tap any step to go straight back to it, or a later one to come forward again. Press and hold the split square to see the original picture while you hold; a tap switches to it and back.', show: 'cleanup' },
  { id: 'statusSwitch', date: '2026-11-20', title: 'On my skin or Planned, at a glance', how: 'Select a tattoo. Right under its name is a two-way switch: On my skin for ink you already have, Planned for one you are thinking about. The filled side is what it is now, and one tap on the other side changes it. Layers shows the same words and marks on each line, and its quick buttons are Hide planned and Hide on my skin.', show: 'statusSwitch' },
  { id: 'handlesTrue', date: '2026-11-19', title: 'Size and turn handles where you expect them', how: 'Select a tattoo. The square handle now sits on its real lower corner and the dot just past its top edge, even on a curved spot or close up, so dragging the square outward always makes it bigger and inward smaller. A big piece seen up close still moves with your finger.', show: 'handles' },
  { id: 'forearmSmooth', date: '2026-11-19', title: 'No more warping on the arm', how: 'Select a tattoo on the forearm or lower leg and drag it. It keeps its shape as it moves: the lines stay straight, and it no longer squashes or flicks between two shapes. Only a piece that goes more than half way round is laid like a sleeve.', show: 'handles' },
  { id: 'trimInk', date: '2026-11-19', title: 'Sizes that match the ink', how: 'Clean up now trims the empty space round the ink when you tap Done, so the box round a tattoo hugs the design and its size in inches is the size of the ink. The ink stays exactly where it was on the body. A tattoo that still has empty space round it says so under its size, with Trim to the ink: one tap, one undo step, and the earlier picture is kept as a version.', show: 'trimInk' },
  { id: 'bodyInches', date: '2026-11-19', title: 'Your body in inches', how: 'Body > Fine-tune each part. Every slider for something a tape can measure now shows it in inches beside it, and the number changes as you slide: neck, chest, waist and hips round, shoulders across, upper arm, forearm, wrist, thigh, calf and ankle round, and the length of the torso, upper arm, forearm, hand, thigh, shin and foot.', show: 'bodyInches' },
  { id: 'bodyTypeIn', date: '2026-11-19', title: 'Type your exact measurements', how: 'Tap any of those numbers and type what your tape says, like 14.5, 14 ½ or 37 cm. The body changes until it measures the same, and every number you typed before is matched again, since a longer leg makes the rest a little smaller to keep your height. Your numbers show in colour; if something else moves them, Match my measurements again puts them back. Your tattoos stay on the same skin at the same real size.', show: 'bodyTypeIn' },
  { id: 'bodyGirth', date: '2026-11-19', title: 'Forearm, wrist and ankle size', how: 'Body > Fine-tune each part has three new sliders: Forearm size and Wrist size under Arms, Ankle size under Legs, each with its measurement round the limb.', show: 'bodyGirth' },
  { id: 'heightExact', date: '2026-11-19', title: 'Type your exact height', how: 'Body > Shape: tap the height under the Height slider and type it, like 5 ft 10.5 in or 179 cm. Changing your height now keeps your tattoos at their real size, so a 3 in piece stays 3 in.', show: 'heightExact' },
  { id: 'cleanupSelect', date: '2026-11-19', title: 'Select part of a tattoo', how: 'Select a tattoo, tap Clean up, then pick Select. Tap a piece of the design to select just that piece (like one half of a mirrored pair), or drag a box or a lasso round part of it. Adds and Takes away build up a selection, and Everything, Flip the selection and Clear sit below. Erase and Restore then only change what is selected.', show: 'cleanup' },
  { id: 'cleanupMove', date: '2026-11-19', title: 'Move, size, turn or flip a piece', how: 'In Clean up, select a piece and tap Move it. Drag it with a finger or the Pencil (it keeps straight across or up and down unless you go off at an angle), pull a corner to size it, the dot to turn it, or use two fingers to do both. Flip, Turn 90° and Copy are below, the arrow keys nudge it, and it shows how far it moved in inches. If it goes past the edge the picture grows, and the tattoo keeps its real size and its spot on the body. Done saves it as a new version and keeps the earlier one.', show: 'cleanup' },
  { id: 'layersOnly', date: '2026-11-19', title: 'Tattoos live in Layers only', how: 'The strip of tattoos along the bottom is gone. Every tattoo is a line in Layers at the right, and Add tattoo (+) and Procreate (the pencil) sit at the top of it, also on the slim rail.', show: 'layersOnly' },
  { id: 'sheetColumn', date: '2026-11-19', title: 'One column at the right', how: 'Select a tattoo: its panel sits under Layers in the same column, and Body, Preview and the other buttons at the top open in that column too, so nothing piles up over the body. Fold the panel down with the arrow next to the bin.', show: 'sheetColumn' },
  { id: 'layersReveal', date: '2026-11-19', title: 'Layers follows what you tap', how: 'Tap a tattoo on the body. Layers opens at its line, unfolds its group and marks it.', show: 'layersReveal' },
  { id: 'lockEdit', date: '2026-11-19', title: 'Locked, but still fine-tune it', how: 'Select a tattoo and tap Lock in place. Taps and drags on the body no longer move it, but size, turn, nudge, blend and colour in its panel still work.', show: 'lockEdit' },
  { id: 'viewLock', date: '2026-11-19', title: 'Lock the view', how: 'Found a view you like? Tap the lock at the end of Full body, Front, Left, Back, Right. Nothing moves the camera until you tap it again, and it comes back locked next time you open the app.', show: 'viewLock' },
  { id: 'selfEyes', date: '2026-11-19', title: 'See it from your own eyes', how: 'Preview > How I see it > My eyes. The view moves behind your own eyes. Drag to turn your head and eyes, only as far as they really go, and pinch to see more or less. Your back, your neck and the backs of your arms stay out of sight, just like in life. Tap a tattoo to hear how much of it you can see.', show: 'selfEyes' },
  { id: 'selfSeen', date: '2026-11-19', title: 'What you can’t see yourself', how: 'Preview > How I see it > What I can’t see. The skin you can only see in a mirror turns darker, worked out from where your head and eyes can turn, leaning forward included. Tap a tattoo for how much of it you can see, and when a pose would show more, Show that pose puts the body in it.', show: 'selfSeen' },
  { id: 'selfMirror', date: '2026-11-19', title: 'Mirror selfie', how: 'Preview > How I see it > Mirror selfie. The body holds a phone at the chest and you see the picture a mirror selfie takes, flipped like the real one, with the phone in it. Pick Right or Left hand and Chest or Face, drag to turn, pinch to step closer or back, then Save picture.', show: 'selfMirror' },
  { id: 'blendModes', date: '2026-11-19', title: 'Blend modes for each tattoo', how: 'Select a tattoo and tap Blend and colour in its panel, or the letter next to it in the Layers panel. Pick Multiply, Colour burn, Linear burn, Darken, Screen, Overlay, Soft light, Hard light, Difference, Hue, Colour, Luminosity and more, like a layer in Procreate. It shows live on the body, goes into what you share, and the layered PSD keeps the same blend mode on each layer.', show: 'blendModes' },
  { id: 'inkColours', date: '2026-11-19', title: 'Change the ink colours', how: 'In Blend and colour, slide Hue, Saturation, Brightness and Contrast, pick a Recolour swatch to turn the ink one colour, or switch on Invert. Each change is one undo step and only changes how the ink looks: your artwork file stays as it was, and Reset colours puts it back.', show: 'inkColours' },
  { id: 'straightArms', date: '2026-11-19', title: 'Straight arms', how: 'Preview > Pose. Right under Standing, Arms straight down, Arms straight out and Palms forward set both elbows fully straight (the standing body keeps them a little bent), so a sleeve or forearm piece shows its whole length. Your tattoos stay on the same skin and you can still move and size them. Standing puts the arms back.', show: 'straightArms' },
  { id: 'cropExact', date: '2026-11-19', title: 'Draw a crop box, then fine-tune it', how: 'In Clean up, pick Crop and drag a box over the picture with a finger or the Pencil. Its position and size now show under Exact size in pixels, so you can nudge a number before you tap Crop.', show: 'cleanup' },
  { id: 'layersDock', date: '2026-11-19', title: 'Layers down the right side', how: 'Tap the layers button at the right edge, under the top bar. It opens a Layers panel the full height of the screen, like Photoshop: every tattoo is a line with its picture, its name and an eye, groups are folders with their own eye, and the dots hold Move earlier, Move later and Lock. Tap the arrow at its top to fold it back to a slim rail. It stays the way you left it.', show: 'layersDock' },
  { id: 'hideKinds', date: '2026-11-19', title: 'Hide planned or on my skin in one tap', how: 'At the top of the Layers panel, or on its slim rail, tap Hide planned to see only the ink already on you, or Hide on my skin to see only what you plan. Tap again to bring them back. It only changes what this screen shows: nothing in your project is hidden or changed.', show: 'hideKinds' },
  { id: 'cleanupStudio', date: '2026-11-19', title: 'A proper cleanup for your artwork', how: 'Select a tattoo and tap Clean up. It opens full screen on the right tool for the picture: Background for art on paper, Cut out for a photo. Six tools sit along the bottom (Cut out, Background, Erase, Restore, Crop, Lines) and only the one in use shows its settings. Pinch to zoom anywhere, Paper strength and Darker lines show as you slide, and Cancel asks before throwing changes away. After you add a photo or art on paper, Clean it up is offered straight away.', show: 'cleanup' },
  { id: 'wrapTurn', date: '2026-11-18', title: 'Turn a band on your ankle or forearm', how: 'Select a band that goes a good way round a lower leg, ankle, forearm or wrist and drag the dot to turn it. It now winds round the limb as one clean band instead of splitting into a V on one side.', show: 'handles' },
  { id: 'wrapResize', date: '2026-11-18', title: 'Drag the corner to grow it into a wrap', how: 'Select a long tattoo on an arm or leg and drag the square corner handle outward. The handle now stays under your finger the whole way, even as the piece starts to go round the limb, and settles on the part facing you when you let go.', show: 'handles' },
  { id: 'wrapGrab', date: '2026-11-17', title: 'Grab a wrap anywhere and slide it round', how: 'A piece that goes round an arm or leg now takes hold wherever you touch it, front, side, round the back or right at its edge, and stays under your finger. Drag sideways to turn it round the limb, up or down to slide it along. Under its name, Wrap it round lays a long piece round the limb with its ends meeting at the back, and the size and turn handles sit on the part facing you.', show: 'wrapGrab' },
  { id: 'wrapQuick', date: '2026-11-17', title: 'Ankle wrap in one screen', how: 'Plan > Measured wrap opens on Quick. Type the bottom and top round the leg and the length, add a picture of the tattoo already there, and tap Make the Procreate file. The old tattoo sits in the middle of the file with the template round it, and the file runs on past the cut so you can draw straight across it. Bring it back and what you drew wraps the leg at that size, with anything past the cut moved round to where that skin is.', show: 'measuredWrap' },
  { id: 'noZoomBoxes', date: '2026-11-17', title: 'No zoom when you tap a box', how: 'Share > Ask for approval > Bring in answers, or a note on a reference picture. Tapping the box to type no longer zooms the whole screen in, so nothing shifts under your finger.', show: 'approval' },
  { id: 'touchScroll', date: '2026-11-17', title: 'Long comments and lists scroll with a finger', how: 'Preview > Comments. The list of comments, a long comment and its replies now scroll with a finger from anywhere on them, not only from a button. The same goes for the Ink check bar and the boxes you type a comment or a note in.', show: 'pins' },
  { id: 'planCards', date: '2026-11-17', title: 'Plan it in neat boxes', how: 'Select a tattoo and open More controls. Under Plan it, the time and rate, the sittings with their dates and tips, the versions and the note for your artist each sit in their own box, so you can see where one ends and the next starts.', show: 'note' },
  { id: 'spotList', date: '2026-11-17', title: 'About this spot as one list', how: 'Select a tattoo and open More controls. About this spot is now one list, a line for each fact (its size as an everyday thing, where it sits, what hides it, how it holds up, how it stretches), with a button like Show that pose at the end of its own line.', show: 'where' },
  { id: 'layersSheet', date: '2026-11-17', title: 'Cleaner Layers and groups', how: 'Plan, then Layers and groups. Each tattoo is one line with its picture, whether it is planned or on you, an eye to hide it, and dots for Move earlier, Move later and Lock. Tick several and their actions show below: Show, Hide, Solo, Lock, ink strength, and a name to group them. Groups are lines too, with Tick these, Rename and Ungroup.', show: 'layersSheet' },
  { id: 'layers3d', date: '2026-11-16', title: 'The 3D body with each tattoo separate', how: 'Procreate (the pencil at the top of Layers, or Share), Send it with each tattoo separate. In Procreate’s 3D painting, open Layers: the skin and every tattoo are their own groups, named like they are here, so you can paint on one tattoo, add layers to it or change its colours without touching the others or the skin.', show: 'layers3d' },
  { id: 'wrapTouch', date: '2026-11-16', title: 'Measured wrap by touch', how: 'Plan > Measured wrap now scrolls with a finger anywhere in its panel, not only on a button, and moves with the keyboard. Pinch the flat view and it keeps your zoom when you switch steps. Trace the old ink with the Pencil while your hand rests on the glass, and lift one of two fingers off a plant to keep moving it.', show: 'measuredWrap' },
  { id: 'layoutsSheet', date: '2026-11-16', title: 'Cleaner Layouts and Projects', how: 'Plan, then Layouts and views. One switch picks Layouts, Checkpoints or Views, one row names and saves what is on the body, and each saved one is a single line with its picture and Open. The dots beside it hold Rename, What’s different and Archive. Compare two and Try a size sit below in their own short groups, and the wipe between two layouts now has a slim bar with both names at the ends. Plan > Projects works the same way: one Save a copy row and one line per project with Open.', show: 'layouts' },
  { id: 'wrapPrint', date: '2026-11-16', title: 'Print the ankle stencil at real size', how: 'Plan > Measured wrap > Print makes a PDF at 100% on Letter, A4, Legal, 8.5 x 16 in or your own size: the stencil with just the new lines, or a placement guide with the old ink, gaps and landmarks to wrap round your ankle first. Longer than the paper, it splits into pages that overlap 10 mm with crosshairs to line up, and every page has a 1 in square to measure.', show: 'measuredWrap' },
  { id: 'wrapProcreate', date: '2026-11-16', title: 'Measured wrap to Procreate and back', how: 'Plan > Measured wrap > Procreate makes a layered file at real size: your garden on top to draw on, and the cactus, its ink, the gaps to keep open, landmarks, cut marks and a 1 cm grid locked underneath. Bring it back and it is checked against the four corner targets before anything changes; a resized file is put back exactly, a stretched one is refused.', show: 'measuredWrap' },
  { id: 'measuredWrap', date: '2026-11-16', title: 'Measured wrap round your ankle', how: 'Plan > Measured wrap. Start with your ankle numbers (9 in and 12.5 in round, 4 in apart), add a photo of the cactus, mark its top flower and stone base, and it is scaled to its real 4 in and placed on the back of the leg. Find the ink protects it and the gaps in it, and plant pictures you add are warned off both.', show: 'measuredWrap' },
  { id: 'segments', date: '2026-11-16', title: 'Switches that look like the iPad’s', how: 'In Body, choices like Male, Neutral and Female or Bald to Long are one switch with the picked one raised, like the iPad’s own settings. Panels at the right now stop above the tattoo list, and the notes under the pain map and Open skin show once, then the bars stay slim.', show: 'hair' },
  { id: 'framing', date: '2026-11-16', title: 'Full body beside the panel', how: 'With a tattoo selected, tap Front, Left, Back or Right: the whole body now fits in the space beside or above the tattoo panel instead of sitting behind it.', show: 'layout' },
  { id: 'editTiles', date: '2026-11-16', title: 'Tidier tattoo panel', how: 'Select a tattoo: its main actions are now a row of picture buttons under the name, like Place by tap, Clean up, Lock and Edit in Procreate, and turn, fade, bend and taper show their value as you slide them.', show: 'editProcreate' },
  { id: 'lists', date: '2026-11-16', title: 'Share, Plan and Procreate as lists', how: 'Open Share, Plan or Procreate: each choice is one row with a picture, its name and one short line, grouped under a heading, so you can find what you want at a glance.', show: 'message' },
  { id: 'feel', date: '2026-11-16', title: 'Moves and reads like an iPad app', how: 'Panels and menus now grow out of the button you tapped and sheets rise into place, and buttons dip under your finger. Preview is one list with a mark beside whatever is on. Text uses the iPad\u2019s own font, and every panel closes with Done. Tips go away once you have followed them, and this badge only counts what is new since you last looked.', show: 'layout' },
  { id: 'bodySections', date: '2026-11-15', title: 'Body in short sections', how: 'Body is now sorted into Shape, From your photos, Skin, Hair, Eyes and Fine-tune each part, each under a small heading. Beard and Body hair have their own labels. The Plan panels use plainer words and only show the buttons that apply, and the full-screen pins and photo tools follow light and dark.', show: 'bodySections' },
  { id: 'plainBody', date: '2026-11-15', title: 'Reset to plain body', how: 'Body, then Reset to plain body takes off anything painted on the skin from Procreate. Every tattoo stays in Layers as its own item. Each tattoo also has a bin next to Done to remove it, locked ones too, and Undo brings anything back.', show: 'plainBody' },
  { id: 'paintChip', date: '2026-11-15', title: 'Paint on skin in the tattoo list', how: 'After you bring a painted body back from Procreate, the paint shows in the tattoo list as Paint on skin. Tap it to make each drawing a movable tattoo, hide it, or remove it for the plain body. Your tattoos stay either way.', show: 'paintChip' },
  { id: 'layout', date: '2026-11-15', title: 'A calmer screen', how: 'Everything now starts from one bar at the top: Body, Preview, Plan and Share, with Undo and Redo as the arrows and the ways to turn the body beside it. Select a tattoo and More controls opens in short sections: size and shape, this spot, checks, planning, copies and the tattoo itself. Plan and Share are sorted the same way. Light or dark follows your iPad.', show: 'layout' },
  { id: 'prefsSync', date: '2026-11-15', title: 'Your settings on every device', how: 'Signed in, your hair, beard, body hair, eye colour, light and hourly rate follow you: change them on the iPad and your phone shows the same a moment later. Turn it off under Account settings in your account. Your face photo stays on the device it was taken on.', show: 'prefsSync' },
  { id: 'chipComments', date: '2026-11-15', title: 'Comment counts in Layers', how: 'A tattoo with open comments pinned on it shows how many on its picture in Layers, in red while one has something new from someone else. Select it and tap Comments to read them.', show: 'pinReplies' },
  { id: 'approveAll', date: '2026-11-15', title: 'Looks good on all', how: 'On a project you work on together, select a planned tattoo and tap Looks good on all to say yes to every planned tattoo nobody has answered yet in one go. Tattoos with an answer or an ask for a change are left as they are, and Undo takes it all back.', show: 'answer' },
  { id: 'findComment', date: '2026-11-15', title: 'Find a comment', how: 'With four or more comments pinned, open Preview > Comments and tap List. Type a word, a name or a tattoo in Find a comment and only the comments that mention it stay, replies included.', show: 'pinFind' },
  { id: 'suggestSpot', date: '2026-11-15', title: 'Suggest a new spot', how: 'Someone you invited to comment only can select a tattoo and tap Suggest a new spot under its name, then move, size or turn it and tap Send suggestion. Nothing moves for anyone else: it arrives as a comment on that spot, and you can press and hold Hold to see it there to look at it in place before you tap Use this spot.', show: 'answer' },
  { id: 'pinNew', date: '2026-11-15', title: 'New comments stand out', how: 'On a project you work on together, a comment or reply from someone else that you have not opened yet puts a red dot on its pin and on Comments in Preview, and says new in the list. Opening it clears the dot.', show: 'pinReplies' },
  { id: 'reacts', date: '2026-11-15', title: 'React to a comment', how: 'On a project you work on together, open a pinned comment in Preview > Comments and tap 👍, ❤️, 🔥 or 👀 under it. Everyone sees who reacted, and tapping it again takes yours back.', show: 'pinReplies' },
  { id: 'mirror', date: '2026-11-15', title: 'In a mirror', how: 'Share, then In a mirror. This view sits beside how it looks when you check it in a mirror, so you can see lettering and one-sided designs the way you will see them every morning.', show: 'mirror' },
  { id: 'bodyChange', date: '2026-11-15', title: 'If your body changes', how: 'Select a tattoo, then Share, then If your body changes. One picture shows it on a slimmer, a heavier and a more muscular you, grown or shrunk with the skin under it, with how much in centimetres.', show: 'bodyChange' },
  { id: 'mention', date: '2026-11-15', title: 'Mention someone in a comment', how: 'On a project you work on together, open Preview > Comments and type @ in a comment or a reply. The names of the people on the project show under it: tap one to mention them. A mention of you stands out in the comment, What changed lists it first, and the comment list has Mentions you to show only those.', show: 'pinReplies' },
  { id: 'ownCopy', date: '2026-11-15', title: 'Make your own copy of a shared project', how: 'On a project someone shared with you, open your account and tap Make my own copy. It goes into your own account as a separate project you can change freely, and the shared one stays as it is for everyone on it.', show: 'ownCopy' },
  { id: 'sleeve', date: '2026-11-15', title: 'Arms and legs, unrolled', how: 'Share, then Arms and legs, unrolled. Each arm and leg’s skin is laid flat side by side with your tattoos on it and a 5 cm grid, the way artists plan a sleeve, so you can see the gaps and what is left.', show: 'sleeve' },
  { id: 'history', date: '2026-11-15', title: 'Go back several steps', how: 'Press and hold Undo. A list shows your last steps in plain words, like Moving Rose or The body shape. Tap one to go back to just before it in one go; Redo brings them back.', show: 'history' },
  { id: 'spotFit', date: '2026-11-15', title: 'Does it fit there', how: 'Select a tattoo, open More controls, then Try other spots. Under each arm and leg spot it now also says when the piece is too long for that part of the limb at its size, or wraps more than half way round it.', show: 'spotCompare' },
  { id: 'colourFade', date: '2026-11-15', title: 'Light colours fade sooner', how: 'Aging and the How it ages picture now fade light colours, pastels and yellow faster than black, the way real ink does, so a colour piece at 20 years looks honest. Try Share, then How it ages, on a tattoo with colour.', show: 'agingSheet' },
  { id: 'distance', date: '2026-11-15', title: 'From a distance', how: 'Select a tattoo, then Share, then From a distance. One picture shows it close up, across a table, across a room and across the street, with the detail an eye can’t make out at each distance run together. Ink check also says from how far its finest lines blur.', show: 'distance' },
  { id: 'stretch', date: '2026-11-15', title: 'How it stretches as you move', how: 'Select a tattoo and open More controls. A line says how much the skin under it stretches and squeezes in the poses that move that spot most, like an arm overhead or a bent knee. Show that pose puts the body in the worst one so you can see it.', show: 'stretch' },
  { id: 'bodyHair', date: '2026-11-15', title: 'Body hair', how: 'Body, then Hair, then Light or Full under the beard. Hair grows on the forearms, lower legs, thighs, the middle of the chest and below the navel, in the hair colour, so you can see how a piece sits with it. Zoom in on a forearm to see single hairs. It stays on this device and changes nothing in the project.', show: 'bodyHair' },
  { id: 'flash', date: '2026-11-15', title: 'Split a flash sheet', how: 'Upload a flash sheet or a page of sketches with several separate designs on it. Tap Split them, or Split into designs in More controls, and each design becomes its own tattoo to place and size. Undo puts the sheet back.', show: 'flash' },
  { id: 'sharp', date: '2026-11-15', title: 'Small artwork warning', how: 'Open Ink check or Stencil for your artist in More controls. When the artwork file is too small to print sharp at the size it has on your body, it says so, and how many pixels wide a sharp file needs to be.', show: 'sharp' },
  { id: 'planStencils', date: '2026-11-15', title: 'Every stencil in one PDF', how: 'With two or more planned tattoos, open Stencil for your artist in More controls and tap All planned pieces. You get one PDF with every planned stencil at its real size, at the Detail you set, ready to print or send to your artist.', show: 'planStencils' },
  { id: 'spotCompare', date: '2026-11-15', title: 'Compare spots', how: 'Select a tattoo and open Try other spots in More controls. Each spot now says how much it usually hurts there and the lightest clothes that hide a piece this size, so you can compare before you move it.', show: 'spotCompare' },
  { id: 'planCal', date: '2026-11-15', title: 'Every sitting in one list', how: 'Give two or more planned tattoos a first sitting date. More controls then lists what is coming up across the whole plan, warns when a sitting lands while another piece is still fresh, and Add every sitting to calendar saves them all at once.', show: 'planCal' },
  { id: 'undoWords', date: '2026-11-15', title: 'Undo says what it put back', how: 'Tap Undo or Redo and a short note says what changed back, like Undid moving Rose or Undid the body shape, so nothing changes out of sight.', show: 'undoWords' },
  { id: 'labels', date: '2026-11-15', title: 'Picture with sizes', how: 'Share > Picture with sizes takes this view with each tattoo’s name, size and where it sits written beside it, in inches and centimetres. Turn the body first so the tattoos you want face you.', show: 'labels' },
  { id: 'centre', date: '2026-11-15', title: 'Centre line while you drag', how: 'Drag a tattoo on your chest, stomach, back or neck across the middle and a guide line shows down the centre of the body. With Snap to guides on (More controls > Precise placement) it sits exactly in the middle.', show: 'centre' },
  { id: 'message', date: '2026-11-15', title: 'Plan as a message', how: 'Share > Plan as a message puts every planned tattoo into a few lines: its size, where it sits the way an artist measures, the time it takes, the first sitting and your note. Send it, or paste it into a text to your artist.', show: 'message' },
  { id: 'keys', date: '2026-11-15', title: 'Keyboard shortcuts', how: 'With a keyboard on the iPad, select a tattoo: the arrows move it the way they point (hold Shift for bigger steps), [ and ] turn it, - and = size it, Cmd+D duplicates it and Delete removes it. Undo puts any of it back.', show: 'keys' },
  { id: 'like', date: '2026-11-15', title: 'Size as an everyday thing', how: 'Select a tattoo and open More controls. The first line says its size as something you know, like about the size of a credit card or a bit smaller than a phone, and follows as you resize it.', show: 'like' },
  { id: 'sitWear', date: '2026-11-15', title: 'What to wear, and how to sleep after', how: 'Select a planned tattoo and open More controls. Under the sittings, a line says what to wear so the spot is open, like a T-shirt for a forearm or shorts for a calf, and another which way to sleep for the first nights. Both go in the calendar entries too. With your artist’s hourly rate set, each sitting shows its cost.', show: 'sitWear' },
  { id: 'covered', date: '2026-11-15', title: 'How covered each area is', how: 'Open Preview > Open skin. Under the summary, a line says how much of each arm, leg, your chest, back and so on is covered so far, and how much with your planned pieces. Handy for planning a sleeve.', show: 'covered' },
  { id: 'reads', date: '2026-11-15', title: 'Who it reads for', how: 'Select a tattoo and open More controls. A line says who it reads the right way up for: others while your arm hangs, or you looking down at it. Turn it to face me (or others) turns it round, one step you can undo.', show: 'reads' },
  { id: 'trip', date: '2026-11-15', title: 'Plan around a trip', how: 'Select a planned tattoo, open More controls and pick the first sitting. Add a trip or beach day: if it lands while the ink is still fresh, it says so and moves the sittings in one tap. The calendar file now says when each sitting can go in the water again.', show: 'trip' },
  { id: 'straight', date: '2026-11-15', title: 'Straighten along the limb', how: 'Select a tattoo and open More controls. A line says how far it is turned off the line of the arm or leg, or off upright on the body. Straighten lines it up, one step you can undo.', show: 'straight' },
  { id: 'wear', date: '2026-11-15', title: 'How it holds up there', how: 'Select a tattoo and open More controls. A line says how that spot treats a tattoo over the years: hands and feet fade faster, creases blur fine lines, sunny spots need sunscreen.', show: 'wear' },
  { id: 'shows', date: '2026-11-15', title: 'What it shows in', how: 'Select a tattoo and open More controls. A line says the lightest everyday clothes that hide it and what shows it, like Hidden by a T-shirt, shows in a tank top. Handy for work or a dress code.', show: 'shows' },
  { id: 'even', date: '2026-11-15', title: 'Even placement', how: 'Select a tattoo near the middle of your chest, back or neck and open More controls: it says how far it is off the centre line, and Centre it puts it right on. For a pair made with Copy to other side, it says how closely the two match, and Match the other side lines them up. Each is one step you can undo.', show: 'even' },
  { id: 'sittings', date: '2026-11-15', title: 'Session planner', how: 'Select a planned tattoo and open More controls. Sittings splits it into outline, shading and finish with time to heal between them. Pick the first date and the weeks between for each date and when it is healed, then Add to calendar.', show: 'sittings' },
  { id: 'versions', date: '2026-11-15', title: 'Design versions', how: 'Edit a tattoo in Procreate or clean it up and the earlier artwork is kept. Select it, open More controls and tap a version to see it on the body. Side by side makes a picture of the two, and Use this one brings it back.', show: 'versions' },
  { id: 'note', date: '2026-11-15', title: 'Note for your artist', how: 'Select a tattoo and open More controls. Type what your artist should know, like fine lines only. It goes on the artist sheet and the artist packet, and Undo takes it back.', show: 'note' },
  { id: 'made', date: '2026-11-15', title: 'Who did it and when', how: 'Select a tattoo marked On my skin and open More controls. Add the artist, the studio and the month it was done. It shows on the artist sheet.', show: 'made' },
  { id: 'plan', date: '2026-11-15', title: 'Time for the whole plan', how: 'With two or more planned tattoos, select one and open More controls. Under its own guess, a line adds up the hours and sessions for every planned piece, with a price if you typed your artist\'s rate.', show: 'estimate' },
  { id: 'tapePose', date: '2026-11-14', title: 'Tape measure in a pose', how: 'Pick a pose in Preview, then Tape measure. The pose stays, and the tape lies on the posed body while it measures along the standing skin, so the length is the one your artist would take.', show: 'tape' },
  { id: 'hairHang', date: '2026-11-14', title: 'Long hair that hangs', how: 'Body, then Hair, then Long, then a pose that bows or tilts the head. The hair now falls from the head the way real hair does, without bunching under the chin or stretching down the back.', show: 'hairLong' },
  { id: 'typing', date: '2026-11-15', title: 'See when someone is replying', how: 'On a project you work on together, open a pinned comment while someone else has the project open. When they start typing a reply to it, the comment says so, like Liv is typing a reply, until they send it.', show: 'pinReplies' },
  { id: 'pointAt', date: '2026-11-15', title: 'Point at a spot for the others', how: 'On a project you work on together, when someone else has it open too, a Point button shows at the top. Tap it, then tap the body: a pulsing ring with your name shows on that spot on their screen, so you can say right here while you talk. Tap Point again to stop.', show: 'pointAt' },
  { id: 'followView', date: '2026-11-15', title: 'Follow their view', how: 'On a project you work on together, when your artist or Liv has it open too, tap their initial next to your account button, then Follow their view. Your screen turns and zooms with theirs, so they can walk you round the body while you talk. Touch the body or tap Stop to look around on your own again.', show: 'followView' },
  { id: 'hereNow', date: '2026-11-15', title: 'See who else has it open', how: 'On a project you work on together, when Liv or your artist has it open too, their initial shows next to your account button, and on the tattoo they have selected in Layers. Tap the initial to see who is here and what each is looking at. Their changes now come through straight away.', show: 'hereNow' },
  { id: 'approvalBrief', date: '2026-11-15', title: 'Reference pictures and comments on the approval page', how: 'Share, then Ask for approval. Each tattoo on the page now shows its reference pictures with their notes and the comments still open on it, with their replies, so your artist gets the whole brief in one place. Pictures and comments for the whole plan come at the end.', show: 'approval' },
  { id: 'refTry', date: '2026-11-15', title: 'Try a reference picture on the body', how: 'Open the reference board and tap a picture, then Try it on the body. It goes on as a planned tattoo where you are looking, so you can size and move it like any other. Clean up artwork in More controls cuts out a photo background. The board keeps its picture.', show: 'refs' },
  { id: 'pinReplies', date: '2026-11-15', title: 'Reply to a comment, then resolve it', how: 'Preview, then Comments, and tap a pin. Type under it and tap Reply to answer right there, like a thread. Tap Resolve when it is sorted: the pin turns grey with a tick and the Comments count only shows the open ones. Reopen brings it back. List shows every comment, open ones first, and tapping one turns the body to it. A selected tattoo shows the comments pinned on it too. Everyone on a shared project can reply and resolve, comment-only people included.', show: 'pinReplies' },
  { id: 'refs', date: '2026-11-15', title: 'Reference board', how: 'Plan your tattoos, then Reference board, or select a tattoo and tap Add reference pictures. Add photos of styles, linework or placement you like, from Photos or pasted, and give each a note. On a project you work on together, everyone sees them and can add their own.', show: 'refs' },
  { id: 'glance', date: '2026-11-15', title: 'Every project at a glance', how: 'Sign in and tap your account button. Every project you own or were invited to is listed with whose turn it is: your turn when someone asked for a change or is waiting on your answer, waiting when it is on them. Tap Your turn to see only those. The account button shows a number when something is waiting on you.', show: 'glance' },
  { id: 'changes', date: '2026-11-15', title: 'What changed since you last looked', how: 'On a project you work on together, come back after the others have worked on it: a message says what changed, and your account panel lists every change, like Liv moved the rose or asked for a change. Tap Show on a line to go to that tattoo or comment.', show: 'changes' },
  { id: 'comment-invite', date: '2026-11-15', title: 'Invite to comment only', how: 'Sign in, tap your account button, Invite someone, then Comments only. Your artist or client can comment, answer Looks good or Ask for a change, and add reference pictures, but cannot move or change your tattoos. You can switch them to Let them edit any time.', show: 'commentInvite' },
  { id: 'together', date: '2026-11-14', title: 'Work on a project together', how: 'Sign in, then tap your account button and Invite someone. Send the link to Liv or your artist: when they open it and sign in, they join this project. You both see the same tattoos, and each other\'s changes arrive by themselves within a few seconds. Only you can rename or remove it, and you can take someone off any time.', show: 'together' },
  { id: 'answer', date: '2026-11-14', title: 'Yes or change, right on the tattoo', how: 'On a project you work on together, select a tattoo: tap Looks good, or Ask for a change and say what, like move it up an inch. It saves into the project with your name and the date, so everyone on it sees it straight away. Take back removes your answer.', show: 'answer' },
  { id: 'pins', date: '2026-11-14', title: 'Comments pinned to the body', how: 'Preview, then Comments. Tap the spot the comment is about and type it, like move this up an inch. A numbered pin stays on that spot through every shape and pose; tap it to read who said it and when. They are in your artist notes too, and people you work with see them.', show: 'pins' },
  { id: 'forgot', date: '2026-11-14', title: 'Forgot your password', how: 'Sign in, I have an account, type your email and tap Forgot your password? Email me a code. Type the code from the email and choose a new password.', show: 'forgot', needs: 'emailCodes' },
  { id: 'room', date: '2026-11-14', title: 'Open skin', how: 'Preview, then Open skin. The body shades from grey where there is no room to deep teal where a big piece still fits, and the top line says how much of you is inked and where the most room is. Tap a spot to read how big a piece fits there.', show: 'room' },
  { id: 'roomFit', date: '2026-11-14', title: 'Find room for a tattoo', how: 'Select a planned tattoo, open More controls, then Find room for it. Green shows everywhere it fits with half an inch to spare. Tap a green spot and it moves there, one undo step.', show: 'roomFit' },
  { id: 'where', date: '2026-11-14', title: 'Where it sits, for your artist', how: 'Select a tattoo and open More controls. The top line says where it sits the way an artist measures it, like 3.2 in below the elbow on the outer forearm.', show: 'where' },
  { id: 'estimate', date: '2026-11-14', title: 'Time to tattoo', how: 'Select a tattoo and open More controls. It gives a rough guess at the hours and sessions from its size and how much ink it has. Type your artist\'s hourly rate for a price.', show: 'estimate' },
  { id: 'accounts', date: '2026-11-14', title: 'Your own account', how: 'Tap Sign in at the top right and make an account with your email and a password. Your project is kept in it as you work: sign in on another iPad, phone or computer and it opens there. To send someone a project, Share, then Send to someone: they open the link and can keep their own copy in their own account.', show: 'account' },
  { id: 'cover', date: '2026-11-14', title: 'Cover-up check', how: 'Mark the old tattoo On my skin, then place the new design over it. Select the new one: the line under its size says how much of the old ink it covers, like Covers 85% of Old rose’s ink, so you can size and move it until nothing shows.', show: 'cover' },
  { id: 'pain', date: '2026-11-14', title: 'Pain map', how: 'Preview, then Pain map. The body turns green where a tattoo usually hurts least and red where it hurts most, from common tattoo pain charts. Tap a spot to read it, or tap a tattoo to see how much it usually hurts over its whole area. It follows your shape and every pose. Done puts it away.', show: 'pain' },
  { id: 'approval', date: '2026-11-14', title: 'Ask your artist or client', how: 'Share, then Ask for approval. Send the page it makes in Messages or Mail. They see each planned tattoo on the body with its size, tap Yes or Change, add a note and send their answers back. Copy their reply, then Share, Bring in answers: each tattoo shows who said yes or what to change.', show: 'approval' },
  { id: 'ink-check', date: '2026-11-14', title: 'Ink check', how: 'Select a tattoo, open More controls, then Ink check. It shows the design on your skin tone and marks colours that barely show, lines under 0.5 mm that will blur with time, and gaps tight enough to fill in. If the lines are too fine, it says the size that fixes them, and Make it bigger does it in one step you can undo.', show: 'inkCheck' },
  { id: 'sizes-sheet', date: '2026-11-14', title: 'Three sizes picture', how: 'Select a tattoo, then Share, then Three sizes. It shows the tattoo a size smaller, as it is now and a size bigger, side by side on the body with each real width, to decide or to send your artist. Your tattoo stays as it is.', show: 'sizesSheet' },
  { id: 'tape', date: '2026-11-14', title: 'Tape measure', how: 'Preview, then Tape measure. Tap two points on the body for the length along the skin between them, the way a tape lies over muscle and round a limb. Tap Around, then one spot, for the way round an arm, a leg, the neck or the waist, and how much of it a tattoo there covers. Done puts it away.', show: 'tape' },
  { id: 'stencil', date: '2026-11-14', title: 'Stencil for your artist', how: 'Select a tattoo, open More controls, then Stencil for your artist. It turns the artwork into clean black lines at its real size on your body, turned the way it sits there. Slide Detail for bolder or finer lines, then Print at real size (with a 1 inch square to check the printer) or Share picture.', show: 'stencil' },
  { id: 'paintLayers', date: '2026-11-14', title: 'Paint in Procreate, get each layer back as a tattoo', how: 'Procreate (next to Upload tattoo), Send the 3D body and choose Procreate. Paint each tattoo on its own layer, then in Procreate tap Actions, Share, Procreate and save to Files. Back here, Bring back your drawing as tattoos: each layer becomes a tattoo named after it that you can move, resize, hide and approve. Your tattoos go out on the body with every send.', show: 'paintLayers' },
  { id: 'beard', date: '2026-11-14', title: 'Beard', how: 'Body, then Hair, then under Beard pick Stubble, Short or Full. It joins the sideburns, keeps the lips bare and ends on the neck under the jaw, in your hair colour. A full beard has real strands and stays on the face in every pose. Kept on this device.', show: 'beard' },
  { id: 'hair-long', date: '2026-11-13', title: 'Long hair', how: 'Body, then Hair, then Long. Parted in the middle, falling round your face to just below the shoulders, in any colour. Match my hair from a photo picks it for longer hair too. In a pose the top moves with your head and the ends with your shoulders, and it moves aside while you work on a tattoo under it. Kept on this device.', show: 'hairLong' },
  { id: 'hair-medium', date: '2026-11-13', title: 'Medium hair', how: 'Body, then Hair, then Medium. Real strands, swept back with some height at the front, in any colour. It stays on the head in every pose. Kept on this device.', show: 'hairMedium' },
  { id: 'photo-ink', date: '2026-11-13', title: 'Your tattoos from a photo', how: 'Body, then Match a photo of me, with a photo of your back, arm or chest that shows your tattoos. Each tattoo it finds gets a box: tap one to leave it out, then Add to the body. They go on as already on me, in the same spot, and undo takes them off.', show: 'photoInk' },
  { id: 'hair-photo', date: '2026-11-13', title: 'Match my hair from a photo', how: 'Body, then Hair, then Match my hair from a photo. Use a photo with your whole head in it. Your hair colour goes on the head, with the nearest length it can show. The photo is not kept.', show: 'hairPhoto' },
  { id: 'eyes', date: '2026-11-13', title: 'Eye colour', how: 'Body, then Eyes. Pick brown, hazel, green, blue, grey or dark brown. With your face on, the first colour is the one from your photo. Kept on this device.', show: 'eyes' },
  { id: 'body-photo-part', date: '2026-11-13', title: 'Match from any photo of you', how: 'Body, then Match a photo of me. A mirror selfie, an upper body shot or a photo of your back works now: it matches the parts it can see and leaves the rest. Add another photo to fill in more. A bare back also offers its skin tone.', show: 'bodyPhoto' },
  { id: 'poses-sheet', date: '2026-11-13', title: 'As you move picture', how: 'Select a tattoo, then Share, then As you move. It shows the tattoo standing and in three poses that move that part of the body, like a flexed arm or a squat.', show: 'posesSheet' },
  { id: 'aging-sheet', date: '2026-11-13', title: 'How it ages picture', how: 'Select a tattoo, then Share, then How it ages. Fresh, healed, 10 and 20 years in one picture, to send to your artist or keep.', show: 'agingSheet' },
  { id: 'hair', date: '2026-11-13', title: 'Shaved or buzz-cut hair', how: 'Body, then Hair. Pick Shaved or Buzz cut and a colour, so the head looks less like a mannequin. Kept on this device.', show: 'hair' },
  { id: 'compare-shot', date: '2026-11-13', title: 'Before and after picture', how: 'Share, then Before and after. This view now and with your planned tattoos, side by side, ready to send.', show: 'compareShot' },
  { id: 'gap', date: '2026-11-13', title: 'Space between tattoos', how: 'Select a tattoo. Under its size, the edit panel says how far it is from the nearest other tattoo, or that they touch. Handy for keeping an even gap.', show: 'gap' },
  { id: 'skin-detail', date: '2026-11-13', title: 'Eyebrows and finer skin', how: 'Zoom in on the face: every body now has eyebrows, and the skin has fine texture up close, like pores.', show: 'skinDetail' },
  { id: 'face', date: '2026-11-13', title: 'Your face on the body', how: 'Body, then Add my face. Pick a clear photo of your face, looking straight at the camera. The head takes your face and its shape. The photo stays on this device, and Hide my face or Remove take it off.', show: 'face' },
  { id: 'body-photo', date: '2026-11-13', title: 'Match a photo of me', how: 'Body, then Match a photo of me. Pick a full-length photo taken straight on and the body takes your shape: shoulders, chest, waist, hips, thighs and how long your torso and legs are.', show: 'bodyPhoto' },
  { id: 'definition', date: '2026-11-13', title: 'More defined body', how: 'Body, then slide Muscle up or Weight down. Abs, chest, shoulders, arms and legs show more, and it follows every pose.', show: 'definition' },
  { id: 'spots', date: '2026-11-13', title: 'Try other spots', how: 'Select a tattoo, open More controls, then Try other spots. One tap moves it to the forearm, calf, ribs, shoulder blade and more, on either side.', show: 'spots' },
  { id: 'try-on', date: '2026-11-13', title: 'Try on with camera', how: 'Select a tattoo, open More controls, then Try on with camera. Point at your skin, move and size it with your fingers, curve it round your arm, then take a photo to share.', show: 'tryOn' },
  { id: 'skin-tone', date: '2026-11-13', title: 'Your own skin tone', how: 'Body, then the + next to the skin colours. Slide lighter or deeper and cooler or warmer, or match a photo of your skin.', show: 'skinTone' },
  { id: 'light', date: '2026-11-13', title: 'Light', how: 'Preview, then Light. See your ink in daylight, a warm room or midday sun.', show: 'light' },
  { id: 'draw-new', date: '2026-11-13', title: 'Draw in Procreate on a spot you paint', how: 'Draw in Procreate under your tattoos. Paint the spot on the body, draw on the guide in Procreate, then Copy All and Paste.', show: 'drawNew' },
  { id: 'other-side', date: '2026-11-13', title: 'Copy to other side', how: 'Select a tattoo, open More controls, then Copy to other side for a mirrored twin.', show: 'otherSide' },
  { id: 'real-size', date: '2026-11-13', title: 'Real size on screen', how: 'Select a tattoo, open More controls, then Real size on screen. Hold the iPad against your skin.', show: 'realSize' },
  { id: 'handles', date: '2026-11-13', title: 'Resize and turn handles', how: 'Select a tattoo, then drag its corner to resize or the dot above it to turn.', show: 'handles' },
  { id: 'palette', date: '2026-11-13', title: 'Colour palette for Procreate', how: 'Share, then Colour palette. Your skin and ink colours as a Procreate palette.', show: 'palette' },
  { id: 'edit-procreate', date: '2026-11-13', title: 'Edit a tattoo in Procreate', how: 'Select a tattoo, then Edit in Procreate. Copy All when done and tap Paste here.', show: 'editProcreate' },
  { id: 'pan', date: '2026-11-13', title: 'Two-finger pan', how: 'Drag two fingers away from a tattoo to slide the view. Twist clearly to turn it.', show: 'pan' },
];

const KEY = 'ia-tried';
export function readTried(storage = globalThis.localStorage) {
  try { const v = JSON.parse(storage?.getItem(KEY) || '[]'); return new Set(Array.isArray(v) ? v.filter((x) => typeof x === 'string') : []); } catch (_) { return new Set(); }
}
export function writeTried(set, storage = globalThis.localStorage) { try { storage?.setItem(KEY, JSON.stringify([...set])); } catch (_) { /* private mode: lasts until reload */ } }
export function untriedCount(tried, list = NEW_FEATURES) { return list.filter((f) => !tried.has(f.id)).length; }
// untried first, newest first within each; tried ones stay at the bottom so they can be found again
export function ordered(tried, list = NEW_FEATURES) { return [...list.filter((f) => !tried.has(f.id)), ...list.filter((f) => tried.has(f.id))]; }
// The badge counts only what has come in since the list was last opened on this device, the way an
// iPad badge clears once you have looked; untried ones stay ticked off in the list itself.
const SEEN = 'ia-new-seen';
export function readSeen(storage = globalThis.localStorage) { try { const a = JSON.parse(storage?.getItem(SEEN) || 'null'); return Array.isArray(a) ? new Set(a) : new Set(); } catch (_) { return new Set(); } }
export function writeSeen(set, storage = globalThis.localStorage) { try { storage?.setItem(SEEN, JSON.stringify([...set])); } catch (_) { /* private mode: lasts until reload */ } }
export function unseenCount(tried, seen, list = NEW_FEATURES) { return list.filter((f) => !tried.has(f.id) && !seen.has(f.id)).length; }
